-- 002_multi_broker: institutions, connections, activity ledger, holdings, FX rates, fee schedules.
-- Rules for this file and everything after it:
--   * Every money column has a currency column beside it. Amounts are stored in that native currency.
--   * Do not edit this file once it has been applied anywhere. Add 003_... instead.
--   * Plain CREATE TABLE (no IF NOT EXISTS) so an unexpected state fails loudly.

-- The brokerage or bank itself.
CREATE TABLE institution (
    institution_id  TEXT PRIMARY KEY,           -- your own slug, e.g. 'wealthsimple', 'demo-maple-broker'
    display_name    TEXT NOT NULL,
    country         TEXT CHECK (country IS NULL OR length(country) = 2),   -- ISO code, e.g. 'CA'
    website_url     TEXT,
    is_demo         INTEGER NOT NULL CHECK (is_demo IN (0,1))
);

-- One data link to an institution (SnapTrade, a CSV export, or synthetic).
-- Credentials never live here: brokerage login happens in the provider's own flow,
-- and API keys / user secrets stay in .env.
CREATE TABLE connection (
    connection_id       TEXT PRIMARY KEY,
    institution_id      TEXT NOT NULL REFERENCES institution(institution_id),
    source_id           TEXT NOT NULL REFERENCES source(source_id),
    display_name        TEXT NOT NULL,
    access_mode         TEXT NOT NULL DEFAULT 'read_only' CHECK (access_mode = 'read_only'),
    status              TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled','error')),
    provider_ref        TEXT,                    -- provider's opaque connection ID only. Never a username,
                                                 -- password, token or secret.
    created_at_utc      TEXT NOT NULL,
    last_synced_at_utc  TEXT,
    is_demo             INTEGER NOT NULL CHECK (is_demo IN (0,1))
);

-- Link existing accounts to an institution and connection. Nullable, so current rows and code still work.
ALTER TABLE account ADD COLUMN institution_id TEXT REFERENCES institution(institution_id);
ALTER TABLE account ADD COLUMN connection_id  TEXT REFERENCES connection(connection_id);

-- Every account event in one ledger, in the currency it happened in.
-- amount = signed net cash effect on the account, fees included (+ in, - out).
-- fee_amount is an informational breakdown of the fee already inside amount.
-- FX_CONVERSION is one row: amount/currency leaves, counter_amount/counter_currency arrives.
CREATE TABLE activity (
    activity_id           TEXT PRIMARY KEY,      -- stable_id(source, provider id or natural key)
    account_id            TEXT NOT NULL REFERENCES account(account_id),
    activity_type         TEXT NOT NULL CHECK (activity_type IN
                            ('BUY','SELL','DIVIDEND','INTEREST','FEE','DEPOSIT','WITHDRAWAL',
                             'TRANSFER_IN','TRANSFER_OUT','FX_CONVERSION','TAX','SPLIT','OTHER')),
    raw_type              TEXT NOT NULL,         -- the broker's own label, kept verbatim
    trade_date            TEXT NOT NULL,         -- YYYY-MM-DD
    settlement_date       TEXT,
    symbol                TEXT,
    description           TEXT,
    quantity              REAL,                  -- units; + received, - delivered
    price                 REAL CHECK (price IS NULL OR price >= 0),
    price_currency        TEXT CHECK (price_currency IS NULL OR length(price_currency) = 3),
    amount                REAL NOT NULL,
    currency              TEXT NOT NULL CHECK (length(currency) = 3),
    fee_amount            REAL CHECK (fee_amount IS NULL OR fee_amount >= 0),
    fee_currency          TEXT CHECK (fee_currency IS NULL OR length(fee_currency) = 3),
    counter_amount        REAL,
    counter_currency      TEXT CHECK (counter_currency IS NULL OR length(counter_currency) = 3),
    reported_fx_rate      REAL CHECK (reported_fx_rate IS NULL OR reported_fx_rate > 0),
                                                 -- broker's rate if given: units of currency leaving
                                                 -- per 1 unit arriving (= |amount| / |counter_amount|)
    provider_activity_id  TEXT,                  -- provider's own ID, if any
    quality_flag          TEXT NOT NULL CHECK (quality_flag IN ('reported','estimated','demo')),
    source_id             TEXT NOT NULL REFERENCES source(source_id),
    batch_id              TEXT NOT NULL REFERENCES import_batch(batch_id),
    loaded_at_utc         TEXT NOT NULL,
    CHECK ((price IS NULL) = (price_currency IS NULL)),
    CHECK ((fee_amount IS NULL) = (fee_currency IS NULL)),
    CHECK ((counter_amount IS NULL) = (counter_currency IS NULL)),
    CHECK (activity_type <> 'FX_CONVERSION'
           OR (counter_amount IS NOT NULL AND counter_currency <> currency))
);
CREATE INDEX ix_activity_account_date ON activity(account_id, trade_date);
CREATE INDEX ix_activity_type ON activity(activity_type);

-- What each account held on a date. Cash balances are rows too (symbol 'CASH.CAD', 'CASH.USD').
CREATE TABLE holding_snapshot (
    account_id             TEXT NOT NULL REFERENCES account(account_id),
    as_of_date             TEXT NOT NULL,        -- YYYY-MM-DD
    symbol                 TEXT NOT NULL,
    asset_class            TEXT NOT NULL CHECK (asset_class IN
                             ('equity','etf','fund','bond','cash','crypto','other')),
    quantity               REAL NOT NULL,
    price                  REAL CHECK (price IS NULL OR price >= 0),
    price_currency         TEXT CHECK (price_currency IS NULL OR length(price_currency) = 3),
    market_value           REAL NOT NULL,
    market_value_currency  TEXT NOT NULL CHECK (length(market_value_currency) = 3),
    book_value             REAL,
    book_value_currency    TEXT CHECK (book_value_currency IS NULL OR length(book_value_currency) = 3),
    quality_flag           TEXT NOT NULL CHECK (quality_flag IN ('reported','estimated','demo')),
    source_id              TEXT NOT NULL REFERENCES source(source_id),
    batch_id               TEXT NOT NULL REFERENCES import_batch(batch_id),
    loaded_at_utc          TEXT NOT NULL,
    PRIMARY KEY (account_id, as_of_date, symbol),
    CHECK ((price IS NULL) = (price_currency IS NULL)),
    CHECK ((book_value IS NULL) = (book_value_currency IS NULL))
);

-- Daily reference rates. Table only in Phase 1: nothing fetches rates yet.
-- rate = units of quote_currency per 1 base_currency (BoC FXUSDCAD 1.37 means 1 USD = 1.37 CAD).
CREATE TABLE fx_rate (
    rate_date       TEXT NOT NULL,               -- YYYY-MM-DD
    base_currency   TEXT NOT NULL CHECK (length(base_currency) = 3),
    quote_currency  TEXT NOT NULL CHECK (length(quote_currency) = 3),
    rate            REAL NOT NULL CHECK (rate > 0),
    series_id       TEXT,                        -- provider's series name, e.g. 'FXUSDCAD'
    quality_flag    TEXT NOT NULL CHECK (quality_flag IN ('reported','estimated','demo')),
    source_id       TEXT NOT NULL REFERENCES source(source_id),
    batch_id        TEXT NOT NULL REFERENCES import_batch(batch_id),
    loaded_at_utc   TEXT NOT NULL,
    PRIMARY KEY (rate_date, base_currency, quote_currency, source_id),
    CHECK (base_currency <> quote_currency)
);

-- Published fees, with where and when you checked them. DEMO rows use example.com URLs.
CREATE TABLE fee_schedule (
    fee_schedule_id  TEXT PRIMARY KEY,
    institution_id   TEXT NOT NULL REFERENCES institution(institution_id),
    fee_type         TEXT NOT NULL CHECK (fee_type IN ('fx_conversion','commission','account','other')),
    applies_to       TEXT,                       -- e.g. 'CAD->USD', 'US equities', 'all accounts'
    rate_bps         REAL CHECK (rate_bps IS NULL OR rate_bps >= 0),          -- 150 = 1.50%
    flat_amount      REAL CHECK (flat_amount IS NULL OR flat_amount >= 0),
    flat_currency    TEXT CHECK (flat_currency IS NULL OR length(flat_currency) = 3),
    effective_from   TEXT,                       -- YYYY-MM-DD
    effective_to     TEXT,                       -- NULL = still current
    source_url       TEXT NOT NULL,
    date_checked     TEXT NOT NULL,              -- YYYY-MM-DD you last confirmed the page
    notes            TEXT,
    is_demo          INTEGER NOT NULL CHECK (is_demo IN (0,1)),
    CHECK (rate_bps IS NOT NULL OR flat_amount IS NOT NULL),
    CHECK ((flat_amount IS NULL) = (flat_currency IS NULL))
);